-- CANDIDATE ONLY: indexed companion lookup, not enabled in the application.
-- Corrected query shape captured from GA4 Traffic Pages, parameterized for any property.
-- psql -v account_id=46 -v date_start=2025-01-01 -v date_end=2026-10-29 -v analyze=false
-- Default EXPLAIN does not execute the aggregation. Analyze mode is opt-in, read-only,
-- and limited to 45 seconds; run it only during a quiet period.
\if :{?analyze}
\else
\set analyze false
\endif
BEGIN READ ONLY;
SET LOCAL statement_timeout = '45s';
\if :analyze
EXPLAIN (ANALYZE, BUFFERS, SETTINGS, FORMAT TEXT)
\else
EXPLAIN (COSTS, VERBOSE, SETTINGS, FORMAT TEXT)
\endif
SELECT COALESCE(dv_dim_landing_page.value, 'unknown') AS "dimensions.landing_page", SUM(CASE WHEN LOWER(mc.name) IN ('screenpageviews') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "screenPageViews", SUM(CASE WHEN LOWER(mc.name) IN ('sessions') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "sessions", CASE WHEN SUM(CASE WHEN LOWER(mc.name) IN ('bouncerate', 'bounce_rate') AND LOWER(mc.period) = 'daily' AND (companion_0.observation_count IS NULL OR companion_0.observation_count <> 1 OR companion_0.weight_value IS NULL OR companion_0.weight_value < 0) THEN 1 ELSE 0 END) > 0 THEN NULL ELSE SUM(CASE WHEN LOWER(mc.name) IN ('bouncerate', 'bounce_rate') AND LOWER(mc.period) = 'daily' THEN m.value * companion_0.weight_value ELSE 0 END) / NULLIF(SUM(CASE WHEN LOWER(mc.name) IN ('bouncerate', 'bounce_rate') AND LOWER(mc.period) = 'daily' THEN companion_0.weight_value ELSE 0 END), 0) END AS "bounceRate", CASE WHEN SUM(CASE WHEN LOWER(mc.name) IN ('averagesessionduration', 'average_session_duration') AND LOWER(mc.period) = 'daily' AND (companion_0.observation_count IS NULL OR companion_0.observation_count <> 1 OR companion_0.weight_value IS NULL OR companion_0.weight_value < 0) THEN 1 ELSE 0 END) > 0 THEN NULL ELSE SUM(CASE WHEN LOWER(mc.name) IN ('averagesessionduration', 'average_session_duration') AND LOWER(mc.period) = 'daily' THEN m.value * companion_0.weight_value ELSE 0 END) / NULLIF(SUM(CASE WHEN LOWER(mc.name) IN ('averagesessionduration', 'average_session_duration') AND LOWER(mc.period) = 'daily' THEN companion_0.weight_value ELSE 0 END), 0) END AS "averageSessionDuration", CASE WHEN COUNT(DISTINCT CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' THEN mc.channeled_account_id END) > 1 AND (COUNT(DISTINCT CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' THEN NULLIF(TRIM(m.metadata #>> '{ga4_report_quality,currencyCode}'), '') END) <> 1 OR MAX(CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' AND NULLIF(TRIM(m.metadata #>> '{ga4_report_quality,currencyCode}'), '') IS NULL THEN 1 ELSE 0 END) = 1) THEN 1 ELSE 0 END AS "_contract_currency_0", SUM(CASE WHEN LOWER(mc.name) IN ('totalrevenue') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "totalRevenue", SUM(CASE WHEN LOWER(mc.name) IN ('conversions') AND LOWER(mc.period) = 'daily' THEN m.value ELSE 0 END) AS "conversions" FROM metrics m JOIN metric_configs mc ON m.metric_config_id = mc.id LEFT JOIN dimension_set_items dsi_dim_landing_page ON mc.dimension_set_id = dsi_dim_landing_page.dimension_set_id AND dsi_dim_landing_page.dimension_value_id IN ( SELECT sub_dv.id FROM dimension_values sub_dv JOIN dimension_keys sub_dk ON sub_dv.dimension_key_id = sub_dk.id WHERE LOWER(sub_dk.name) = 'landing_page' ) LEFT JOIN dimension_values dv_dim_landing_page ON dsi_dim_landing_page.dimension_value_id = dv_dim_landing_page.id LEFT JOIN dimension_set_items dsi_dim_filter_scope ON mc.dimension_set_id = dsi_dim_filter_scope.dimension_set_id AND dsi_dim_filter_scope.dimension_value_id IN ( SELECT sub_dv.id FROM dimension_values sub_dv JOIN dimension_keys sub_dk ON sub_dv.dimension_key_id = sub_dk.id WHERE LOWER(sub_dk.name) = 'scope' ) LEFT JOIN dimension_values dv_dim_filter_scope ON dsi_dim_filter_scope.dimension_value_id = dv_dim_filter_scope.id LEFT JOIN LATERAL (SELECT COUNT(*) AS observation_count, MAX(wm.value) AS weight_value FROM metric_configs wc JOIN metrics wm ON wm.metric_config_id = wc.id WHERE wm.metric_date = m.metric_date AND wc.channel = mc.channel AND LOWER(wc.name) IN ('sessions') AND LOWER(wc.period) = LOWER(mc.period) AND wc.account_id IS NOT DISTINCT FROM mc.account_id AND (wc.channeled_account_id = mc.channeled_account_id OR (wc.channeled_account_id IS NULL AND mc.channeled_account_id IS NULL)) AND wc.campaign_id IS NOT DISTINCT FROM mc.campaign_id AND wc.channeled_campaign_id IS NOT DISTINCT FROM mc.channeled_campaign_id AND wc.channeled_ad_group_id IS NOT DISTINCT FROM mc.channeled_ad_group_id AND wc.channeled_ad_id IS NOT DISTINCT FROM mc.channeled_ad_id AND wc.creative_id IS NOT DISTINCT FROM mc.creative_id AND wc.event_id IS NOT DISTINCT FROM mc.event_id AND wc.channeled_event_id IS NOT DISTINCT FROM mc.channeled_event_id AND wc.page_id IS NOT DISTINCT FROM mc.page_id AND wc.post_id IS NOT DISTINCT FROM mc.post_id AND wc.product_id IS NOT DISTINCT FROM mc.product_id AND wc.customer_id IS NOT DISTINCT FROM mc.customer_id AND wc.order_id IS NOT DISTINCT FROM mc.order_id AND wc.query_id IS NOT DISTINCT FROM mc.query_id AND wc.country_id IS NOT DISTINCT FROM mc.country_id AND wc.device_id IS NOT DISTINCT FROM mc.device_id AND (wc.dimension_set_id = mc.dimension_set_id OR (wc.dimension_set_id IS NULL AND mc.dimension_set_id IS NULL)) AND wc.location_id IS NOT DISTINCT FROM mc.location_id AND wc.state_id IS NOT DISTINCT FROM mc.state_id AND wc.city_id IS NOT DISTINCT FROM mc.city_id AND LOWER(mc.name) IN ('averagesessionduration','average_session_duration','bouncerate','bounce_rate')) companion_0 ON TRUE WHERE mc.channel IN (SELECT id FROM channels WHERE name IN ('google_analytics')) AND m.metric_date >= :'date_start' AND m.metric_date <= :'date_end' AND mc.channeled_account_id = :'account_id' AND dv_dim_filter_scope.value = 'traffic_matrix' AND LOWER(mc.name) IN ('screenpageviews', 'sessions', 'bouncerate', 'bounce_rate', 'averagesessionduration', 'average_session_duration', 'totalrevenue', 'conversions') AND LOWER(mc.period) = 'daily' GROUP BY COALESCE(dv_dim_landing_page.value, 'unknown') ;
ROLLBACK;
